N=26
out=[[0]*N for _ in range(N)]
objs={
8: (0,0, [(r,4) for r in range(8,14)], [(8,5),(13,5)]),
6: (7,-6, [(2,12),(3,12),(3,13),(3,14),(3,15),(4,12),(5,12),(6,12),(6,13),(6,14),(6,15),(7,12)], [(2,11),(3,16),(6,16),(7,11)]),
5: (-10,9, [(19,2),(19,3),(20,2),(21,2),(22,2),(22,5),(23,2),(23,5),(24,2),(24,3),(24,4),(24,5)], [(19,4),(20,1),(21,5),(23,1)]),
4: (-6,3, [(r,c) for r in range(12,17) for c in range(11,15)], [(11,14),(15,10),(16,15),(17,11)]),
9: (1,-4, [(3,c) for c in range(21,25)]+[(r,24) for r in range(4,9)]+[(9,23),(9,24)], [(2,24),(3,25),(4,21),(9,22)]),
7: (-18,4, [(18,c) for c in range(16,20)]+[(19,16),(19,19),(20,16),(20,19),(21,19),(22,18),(22,19)], [(18,15),(20,15),(21,16),(22,17)]),
}
# lower 9 separate add
lower9=((-13,-5),[(13,22),(13,23),(14,22),(15,22),(15,23)],[(13,24),(15,24)])
placements={}
for color,(dr,dc,pix,marks) in objs.items():
    placements[color]=([(r+dr,c+dc) for r,c in pix],[(r+dr,c+dc) for r,c in marks])
placements['9b']=([(r-13,c-5) for r,c in lower9[1]],[(r-13,c-5) for r,c in lower9[2]])
for color,(pix,marks) in placements.items():
    for r,c in pix:
        if not (0<=r<N and 0<=c<N): print('OOB pixel',color,r,c)
        if out[r][c]: print('collision pixel',color,r,c,out[r][c])
        out[r][c]=int(color[0]) if isinstance(color,str) else color
for color,(pix,marks) in placements.items():
    for r,c in marks:
        if not (0<=r<N and 0<=c<N): print('OOB marker',color,r,c)
        if out[r][c] not in (0,2): print('marker overlaps pixel',color,r,c,out[r][c])
        out[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in out))

# update translations, anchor color 4 at original location
trans={8:(7,-3),6:(13,-9),5:(-4,6),4:(0,0),9:(7,-7),7:(-12,1)}
out2=[[0]*26 for _ in range(26)]
for color,(dr,dc) in trans.items():
    pix,marks=objs[color][2],objs[color][3]
    for r,c in pix:
        rr,cc=r+dr,c+dc
        if not (0<=rr<26 and 0<=cc<26): print('OOB',color,rr,cc)
        if out2[rr][cc] not in (0,color): print('collision',color,rr,cc,out2[rr][cc])
        out2[rr][cc]=color
    for r,c in marks:
        rr,cc=r+dr,c+dc
        if out2[rr][cc] not in (0,2): print('marker-overlap',color,rr,cc,out2[rr][cc])
        out2[rr][cc]=2
# lower9 t=(-7,-8)
for r,c in lower9[1]: out2[r-7][c-8]=9
for r,c in lower9[2]: out2[r-7][c-8]=2
print('\n'.join(' '.join(map(str,r)) for r in out2))
